// WET: discount logic duplicated in two places
public class OrderController {
    public BigDecimal calculateTotal(Order order) {
        var subtotal = order.getSubtotal();
        // Duplicate: 10% discount for orders over 1000
        return subtotal.compareTo(new BigDecimal("1000")) > 0 
            ? subtotal.multiply(new BigDecimal("0.9")) 
            : subtotal;
    }
}

public class InvoiceService {
    public BigDecimal finalizeInvoice(Order order) {
        var subtotal = order.getSubtotal();
        // Same 10% discount logic repeated
        return subtotal.compareTo(new BigDecimal("1000")) > 0 
            ? subtotal.multiply(new BigDecimal("0.9")) 
            : subtotal;
    }
}

// DRY: single source of truth
public class DiscountService {
    public BigDecimal applyBulkDiscount(BigDecimal subtotal) {
        return subtotal.compareTo(new BigDecimal("1000")) > 0 
            ? subtotal.multiply(new BigDecimal("0.9")) 
            : subtotal;
    }
}

// Now both use the single authoritative implementation
public class OrderController {
    private final DiscountService discountService;

    public BigDecimal calculateTotal(Order order) {
        return discountService.applyBulkDiscount(order.getSubtotal());
    }
}

// Over-engineered: unnecessary abstraction
public interface Validator<T> {
    boolean validate(T item);
}

public class EmailValidator implements Validator<String> {
    public boolean validate(String email) {
        return email != null && email.contains("@");
    }
}

public class ValidatorFactory {
    public static <T> Validator<T> getValidator(Class<T> type) {
        if (type == String.class) return (Validator<T>) new EmailValidator();
        throw new IllegalArgumentException();
    }
}

