class Pricing {
    // DRY: one source of truth for the discount rule
    private static final double MEMBER_DISCOUNT = 0.10;

    // KISS: the simplest thing that works -- no rules engine, no plugins (YAGNI)
    double finalPrice(double price, boolean member) {
        return member ? price * (1 - MEMBER_DISCOUNT) : price;
    }
}
// DRY:  don't scatter 0.10 across the codebase.
// KISS: a ternary, not an over-engineered strategy framework.
// YAGNI: no tiered-loyalty engine until the business actually asks for it.
```
The three principles pull together: remove duplication, keep it simple, and don't build for imaginary futures.

// Over-applied DRY: forcing abstraction too early
public class DateFormatter {
    // Trying to handle two different use cases in one method
    public String format(LocalDateTime date, boolean forCustomer) {
        if (forCustomer) {
            var now = LocalDateTime.now();
            var hours = ChronoUnit.HOURS.between(date, now);
            return hours < 24 ? hours + " hours ago" : date.toString();
        } else {
            return date.format(DateTimeFormatter.ISO_DATE_TIME);
        }
    }
}

// Better: separate methods for separate concerns
public class CustomerDateFormatter {
    public String toRelativeTime(LocalDateTime date) {
        var now = LocalDateTime.now();
        var hours = ChronoUnit.HOURS.between(date, now);
        if (hours < 1) return "Just now";
        if (hours < 24) return hours + " hours ago";
        return date.format(DateTimeFormatter.ofPattern("MMM d"));
    }
}

public class AuditLogFormatter {
    public String toIsoTimestamp(LocalDateTime date) {
        return date.format(DateTimeFormatter.ISO_DATE_TIME);
    }
}

